import{_ as a,C as t,o as r,c as o,j as i,a as l,E as n,a5 as s}from"./chunks/framework.DNkHA0lr.js";const g=JSON.parse('{"title":"精神美学：如何打造美丽心智","description":"","frontmatter":{"title":"精神美学：如何打造美丽心智","originalTitle":"Mental Aesthetics: How To Build A Beautiful Mind","date":"2023-09-07","originalUrl":"https://thedankoe.com/letters/mental-aesthetics-how-to-build-a-beautiful-mind/","minutes":22,"sourceHash":"515e98e7fa5730ead2055a8a6d4412a4e716ace2f380ee78ac9be75bfbd57d79","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/mental-aesthetics-how-to-build-a-beautiful-mind/"}]]},"headers":[],"relativePath":"letters/mental-aesthetics-how-to-build-a-beautiful-mind.md","filePath":"letters/mental-aesthetics-how-to-build-a-beautiful-mind.md"}'),h={name:"letters/mental-aesthetics-how-to-build-a-beautiful-mind.md"};function d(c,p,u,m,I,b){const e=t("ArticleMeta");return r(),o("div",null,[p[0]||(p[0]=i("h1",{id:"精神美学-如何打造美丽心智",tabindex:"-1"},[l("精神美学：如何打造美丽心智 "),i("a",{class:"header-anchor",href:"#精神美学-如何打造美丽心智","aria-label":'Permalink to "精神美学：如何打造美丽心智"'},"​")],-1)),n(e),p[1]||(p[1]=s('<p><a href="https://www.youtube.com/embed/BoxC63ZvCnU?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>你能得到的最好赞美之一就是：“我喜欢你大脑运转的方式。”</p><p>在我年轻的时候，我总是嫉妒那些比我更聪明的人。</p><p>他们是怎么做到的？</p><p>他们是如何如此清晰地表达自己的想法的？</p><p>他们怎么能把我多年来一直在想却无法组织成语言的话说出来呢？</p><p>他们是如何以一种令人敬畏的理解力来进行高水平对话的？那种感觉就像在知识层面上，你被他们远远甩在下面一样。</p><p>我曾试图模仿斯多葛学派、古人以及现代大师的声音。但我很快意识到，语言的进化是有原因的。我们拥有更多样化的工具集，可以穿透噪音并获取真相。</p><p>瓦茨（Watts）的诗意。</p><p>塞内卡（Seneca）的精辟建议。</p><p>尼采（Nietsche）的晦涩。</p><p>彼得森（Peterson）的优雅。</p><p>他们的话语中有一种分量，深深印在我的脑海深处。</p><p>回想起来，正是这些指引我走到了今天。</p><p>我一直想做一些有创意的事情。</p><p>我知道我不想靠出卖体力谋生，也不想靠出卖时间谋生。我必须靠我的头脑赚钱。</p><p>这让我走上了一条充满生活与商业失败的残酷道路，但也正是这条路，让我发现并培养了高价值技能。</p><p>设计、营销、销售、技术、编程、写作、影视制作等等，这些训练了我的大脑去进行创造性的问题解决。</p><p>今天，我很感激地说，我可以通过拨动两个杠杆来谋生并维持高质量的生活：我大脑的输入和输出。</p><p>在这封信中，我想探讨4个核心观点：</p><ol><li>你的精神躯体及其如何主宰你的生活。</li><li>为什么精神健美是你通往智慧的路径。</li><li>为什么精神地产是最有价值的资源。</li><li>如何将你的心智变现，创造属于你自己的收入来源。</li></ol><p>精神美学是你开启美好生活大门的万能钥匙。</p><h2 id="i-–-精神躯体" tabindex="-1">I – 精神躯体 <a class="header-anchor" href="#i-–-精神躯体" aria-label="Permalink to &quot;I – 精神躯体&quot;">​</a></h2><p>在麦克斯韦·马尔茨（Maxwell Waltz）的《心理控制论》（Psycho-Cybernetics）一书中，提到过这样一种现象：整形手术患者在改变了外貌之后，他们的生活发生了翻天覆地的变化。</p><p>许多患者后来实现了他们最疯狂的梦想。</p><p>那些他们以前认为不可能实现的梦想，哪怕阻碍他们的“瑕疵”仅仅是鼻子上一个（常人根本注意不到的）小肿块。</p><p>但产生改变的并不是外貌本身。</p><p>而是自我形象的改变。</p><p>是他们在心理构建中所持有的那个躯体的改变，而这个心理躯体往往并不能真实反映他们的身体外貌。</p><p>这引出了预期与现实的原则。</p><p>人类倾向于抓住思想、观念和信念，以此来理解世界并帮助自己生存。</p><p>我们在脑海中持有一个关于过去或未来的<em>观念</em>，如果当前的现实与之不符，就会产生张力。</p><p>张力会使心智变得狭隘，并产生压力。</p><p>它阻碍了你看清世界的本来面目，因为世界除了它<em>原本的样子</em>之外，本就不该是其他任何模样。</p><p>当我们在脑海中持有一个“我们认为自己是谁”的形象时——即使我们从未在外部倒影之外直接看过自己的脸——任何挑战该形象的事物都会被视为一种威胁。</p><p>即使是在大众眼中被票选为拥有最美体格的健身模特，也会患有躯体变形障碍。</p><p><em>见鬼，就连我在健身房泡了10年之后也有了躯体变形障碍。</em></p><p>他们认知的自我形象与他们的实际外貌并不匹配。</p><p>这影响了我们如何感知和解释周围的世界。</p><p>像一顿不健康饮食的想法这么简单的事情，就能让一个健身模特陷入愤怒的情绪漩涡，因过去的一次暴饮暴食而产生自我厌恶，并产生一种冲动，想要向所有人说教，要求他们必须遵守自己信奉的饮食理念。</p><p>对于我们认为自己“是什么”的一切事物，情况同样如此。</p><p>从宗教信仰到预算技巧，再到让我们赖以生存的商业模式和工作，当我们在脑海中创造出与生活的无常不相符的永恒性时，我们的身份认同就会变味。</p><h3 id="i-i-–-概念性生存" tabindex="-1">I.i – 概念性生存 <a class="header-anchor" href="#i-i-–-概念性生存" aria-label="Permalink to &quot;I.i – 概念性生存&quot;">​</a></h3><p>如其在上，如其在下。</p><p>人类同时在物质和精神两个存在层面上生存。</p><p>是的，如果有一头熊向你冲来，你的一生会在你眼前闪现。</p><p>但即便如此，我依然认为人类仅仅是在精神层面上生存。</p><p>当熊向你冲来时，你并不是<em>真的</em>担心你的肉身。你担心的是肉身背后的那个概念。</p><p>在生命终结前的有限时间里，你的脑海中会涌现出你即将失去的朋友、家人、事业以及其他任何概念，你担心的其实是这些。</p><p>你的“自我”才是你试图去保全的东西。</p><p>如果它受到了威胁，你就会有感觉。</p><p>如果你迷恋一支运动队，而有人说那支队伍糟透了，你会有什么感觉？</p><p>如果你信奉某种特定的宗教，而有人告诉你他们的宗教更好，你会有什么感觉？你是否想通过交流把你脑子里的东西复制到他们脑子里，好让你的精神后代得以存活，并指望着能让他们皈依？</p><p>如果你自认为是个爱喝咖啡的人，而咖啡刚好喝完了，你这一天是不是就毁了？</p><p>在现实中，一切都好。</p><p>你并没有处于真正的危险之中，你的肉身每秒钟都在细胞层面上发生变化。你不是你的躯体，因为你的躯体跟7年前相比已经100%不同了。你是意识。</p><p>当你试图让任何事物变得永恒时，你就增加了痛苦的几率。</p><p>要玩这场生活游戏，你必须选择什么是值得受苦的，并将你的一生奉献于此。</p><p>成功人士利用他们的情绪。失败者则被情绪所利用。</p><h3 id="i-ii-–-课题-释放概念" tabindex="-1">I.ii – 课题：释放概念 <a class="header-anchor" href="#i-ii-–-课题-释放概念" aria-label="Permalink to &quot;I.ii – 课题：释放概念&quot;">​</a></h3><p>自我发展就是认知发展。</p><p>为了发展、扩展和成长你自己——不要与<em>膨胀</em>你的自负相混淆——你必须像解开绑在热气球上的沙袋一样，释放那些阻碍你上升的观念。</p><p>当你感到张力、压力或负面情绪升起时，你必须训练自己停下来。</p><p>这是一项终生的正念追求。</p><p>这是要实现美好生活所必须养成的一个习惯。</p><p>它不是可有可无的选项。</p><p>当你停下来时，识别出你脑海中的预期，以及当下的现实情况。</p><p>我们不想与生活开战，我们想与它融为一体。</p><p>我们不想对抗它，而是要顺应它流动。</p><p>放下那些阻碍你的不合理信念，不要管你的感觉如何去采取行动，因为你做得到。</p><h2 id="ii-–-精神健美" tabindex="-1">II – 精神健美 <a class="header-anchor" href="#ii-–-精神健美" aria-label="Permalink to &quot;II – 精神健美&quot;">​</a></h2><blockquote><p>当大多数人的自我意识是外部世界的产物时，你却有机会剥开这些表层。你可以建立一个有意识的、个人创造的自我，让你工作得更少，赚得更多，并享受生活。——<a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">专注的艺术（The Art Of Focus）</a></p></blockquote><p>世界上薪水最高的人是战略家、远见卓识者和真正的创作者。</p><p>最充实的人是那些能够控制自己心智的人。</p><p>那些得到自己想要的东西的人，已经塑造出了一个让他们的理想未来成为必然的自我。</p><p>你的“自我”是一个理念。</p><p>一个概念。</p><p>一套通过学习被条件反射般植入你脑海的信念。当我们年轻时，我们像海绵一样吸收外部信息。</p><p>这些信息往往是由你的父母传承下来的，而他们又受到了社会、政府和文化的影响——特别是如果他们从不质疑那些信念的话。</p><p>这正是你过着平庸生活的原因。</p><p>因为你做着别人告诉你该做的事。</p><p>因为你让自己的注意力被夺走。</p><p>因为有一天你醒来，发现自己完全按照别人所说的“能通向幸福”的方式去做了，结果换来的只有不幸福。</p><p>精神健美是雕琢你的心理躯体，直至在健康、财富、人际关系和幸福方面达到理想结果的行为。</p><p>为了打造你理想的精神体格，你得接受这条路将充满痛苦。</p><p>现在的“你”，只是被投射在你身上的一堆局限性的集合。</p><p>你的任务就是意识到这些局限，释放它们，并增加你自我的复杂性。</p><p>“自我的复杂性”指的是你拥有的知识、技能和信念，它决定了你在航行于人生中时能产生多少清晰度。</p><p>在这个模糊的世界里，清晰的头脑是一项资产。</p><p>清晰度，或者说想明白，或者说有序的意识，是享受生活的主要成分。</p><p>问题在于，当涉及到做自己想做的事情时，大多数人都是焦虑、不知所措和充满不确定性的。</p><h3 id="ii-i-–-信息代谢" tabindex="-1">II.i – 信息代谢 <a class="header-anchor" href="#ii-i-–-信息代谢" aria-label="Permalink to &quot;II.i – 信息代谢&quot;">​</a></h3><p>生活就是经历，而经历就是信息。</p><p>你的心智决定了你的生活质量，因为你的发展决定了你如何处理信息，或者说你如何处理生活。</p><p>当信息令你应接不暇时，你会感到焦虑。</p><p>当信息让你提不起劲时，你会感到无聊。</p><p>为了最大化信息流，把你的大脑想象成现实的消化系统。</p><p>如果你吃得太多或运动得太少，你就无法代谢那些经历。</p><p>如果你吃得太少或运动得太多，你就会饥饿和烦躁。</p><p>当你吃得刚刚好时，你就创造了一个有利于精神肌肉生长的环境。你跋涉穿过现实，向着你的目标前进。你进入了一个纯粹进步的季节，那种感觉不可思议。</p><h3 id="ii-ii-–-增肌与减脂" tabindex="-1">II.ii – 增肌与减脂 <a class="header-anchor" href="#ii-ii-–-增肌与减脂" aria-label="Permalink to &quot;II.ii – 增肌与减脂&quot;">​</a></h3><p>在健身中，你通过创造一个有利于肌肉生长的环境来增肌。</p><p>你需要充足的食物、睡眠、训练强度和一致性。</p><p>在这个过程中你会增加一些脂肪。如果你想看到明显的结果，这是不可避免的。</p><p>在某个阶段，你会开始感觉不对劲。</p><p>你感到昏昏沉沉和迟缓，你不喜欢镜子里自己看起来那么松垮垮的样子。</p><p>为了让新长出的肌肉显现出来，你改变你的环境以反映你的新目标。</p><p>你减少进食量——或者增加训练量——以此来维持你在增肌期练出的肌肉。</p><p><strong>一个关键点：</strong></p><p><em>你需要为生命中的每个篇章设定一个有意识的目标。</em></p><p>目标既提供了愿景，也提供了一种叙事，让你的头脑变得有序。</p><p>一个篇章的两个主要主题将是连贯性或强度。</p><p>为你的人生设定的目标、愿景和叙事，为你提供了一个感知过滤器，以消化正确的信息。我们可以把这些看作是营养分配的机制。</p><p>当你利用了你吸收的信息中正确的部分时，你增肌的速度就会比平时更快。</p><p>为了强健你的精神体格，你必须去推开未知的边界。</p><p>尝试新事物，飞越整个国家，开始创业，并用信息淹没自己，这样你就能过滤出能让你把这些事情做好的深刻见解。</p><p>当你碰壁时，后退一步。</p><p>休息，恢复，并通过觉察与理解，甩掉你的头脑在这一路上积攒的脂肪。</p><p>在一个进步的篇章之后休息一下是完全没问题的。</p><h3 id="ii-iii-–-训练心智" tabindex="-1">II.iii – 训练心智 <a class="header-anchor" href="#ii-iii-–-训练心智" aria-label="Permalink to &quot;II.iii – 训练心智&quot;">​</a></h3><p>短内容是目前互联网的通用语言。</p><p>普通人已经把他们的大脑训练成了思维短浅、眼界狭隘的机器，而且很难去展望一个积极的未来。</p><p>训练你的心智就是训练你的自我理念。</p><p>你的自我，或者说身份认同，被你的世界观所局限。</p><p>为了将我们自身扩展到拥有浩瀚知识、经验和专长的境界，我们必须将心智扩展到超越肤浅的快乐和问题之上。</p><p>读更长的书。听更长的播客。与你亲近的人进行更深入的对话。</p><p>打破那种在没有精通的哲学支撑下，盲目循环性、金钱和放纵观念的无脑怪圈。</p><p>记住，你需要一个人生目标。</p><p>一个志向。</p><p>一个供你朝着它前进、并以此来校准你决策的事物。</p><p>这对你的心智输出大有裨益。</p><p>只有消费没有创造，是走不远的。</p><p>这就像暴饮暴食却不去举铁。大部分热量都会转化为脂肪囤积起来。你并没有把营养的效用发挥到极致。</p><p>阅读、倾听和消费，必须与写作、演讲以及构建一个对人类有贡献的产品保持平衡。这就是你找到连结感与充实感的方式。</p><p>在这封信的结尾，我们会把所有这些串联成可落地的实操步骤。跟紧我。</p><h3 id="ii-iv-–-有意义的事件" tabindex="-1">II.iv – 有意义的事件 <a class="header-anchor" href="#ii-iv-–-有意义的事件" aria-label="Permalink to &quot;II.iv – 有意义的事件&quot;">​</a></h3><p>当你通过消费与创造的平衡，让生活中的信息流达到最大化时，你就会遇到有意义的事件。</p><p>你会<em>感受</em>到对未来的深深兴奋、对当下的充实，以及对过去的感激。</p><p>这些感觉应该被视为一种契机，去记录你生活中那些可以与他人分享的重要部分。</p><p>当你读到一本好书，偶然发现一个让你兴奋的道理时，把它写下来。</p><p>当你因为取得的进展而对当下感到充实时，把它写下来。</p><p>当你感激你的过去引导你来到此刻，即便你曾犯下错误时，把它写下来。</p><p>随着你记录的信号不断增加，你就拥有了可以用来复制这些体验的数据。</p><p>你可以训练你的心智，将占据这些意识状态作为一种基准线。</p><p>你的生活质量会提升到一个高度稳定的水平。</p><h3 id="ii-v-–-这一课-探索未知" tabindex="-1">II.v – 这一课：探索未知 <a class="header-anchor" href="#ii-v-–-这一课-探索未知" aria-label="Permalink to &quot;II.v – 这一课：探索未知&quot;">​</a></h3><p>你还没到达你想要去的地方，是因为你在原地待得太久了。</p><p>扩展心智（和潜力）的方式，就是去解决那些阻碍你实现目标的问题。</p><p>你的目标潜藏在未知之中。</p><p>对未知的<em>想象</em>会产生紧绷感和恐惧。</p><p>拖延解决生活中的问题，正在让你付出什么代价？</p><p>第一种人决定在一天之内解决问题。</p><p>第二种人决定忍受停滞的痛苦，要么一个月后解决，要么根本不去解决。</p><p>当第二种人达成1个目标时，第一种人已经达成了30个目标。</p><p>你讨厌你的工作，但它带来的痛苦并没有你对未知的恐惧那么强烈，所以你没有去追求做自己事情的目标。</p><p>你讨厌你住的地方，但还没讨厌到愿意付出必要的努力搬出去的地步。</p><p>你讨厌你的伴侣，但还没讨厌到愿意培养一点自尊的程度。</p><p>醒醒吧，别再用那种狭隘的方式生活了。</p><p>爱上你在坚持不懈追求目标的过程中学到的功课。</p><h2 id="iii-–-精神不动产" tabindex="-1">III – 精神不动产 <a class="header-anchor" href="#iii-–-精神不动产" aria-label="Permalink to &quot;III – 精神不动产&quot;">​</a></h2><blockquote><p>无论积极还是消极，占据集体精神不动产的观念，都将影响我们作为一个物种所取得的进步。未来属于那些能够用有价值的信息尽可能长久地捕获并留住注意力的人。—— <a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">《专注的艺术》(The Art Of Focus)</a></p></blockquote><p>是谁在你脑海里写下了代码？</p><p>也就是说，是谁喂给你那些塑造了你自我认知的信息、观念、信念、视角和世界观？</p><p>让我们把你的“自我”看作一个智性上的构建物。</p><p>一具精神躯体。</p><p>一栋可以被你允许免租入住的房客所占据、滋养或摧毁的房子。</p><p>互联网随之而来。</p><p>社交媒体随之而来。</p><p>就这样，我们每天都有成千上万个观念在塑造我们是谁、我们如何行动，以及我们在乎什么。</p><p>大多数人甚至不知道自己为什么要做正在做的事。</p><p>单凭这一点，就是一种审查你生活的绝佳方式。</p><p>如果你不知道自己<em>为什么</em>要去上那门课、去做那份工作、去跟那个人结婚，或者去做你正在做的任何事，那你就没有在创造你自己。</p><p>在一个注意力涣散的世界里，保持长期的专注是一门失传的艺术，而这正在摧毁我们成就任何有意义之事的能力。</p><h3 id="iii-i-–-拨动社交开关" tabindex="-1">III.i – 拨动社交开关 <a class="header-anchor" href="#iii-i-–-拨动社交开关" aria-label="Permalink to &quot;III.i – 拨动社交开关&quot;">​</a></h3><p>如果你把它看作魔鬼，社交媒体就是魔鬼。</p><p>如果你把它看作潜能的载体，社交媒体就是你潜能的载体。</p><p>你如何看待机遇，取决于你的自我发展（self-development）。</p><p>如果你不认为自己是个作家，你就不会把一篇疯传的社交媒体帖子视为灵感。</p><p>如果你不认为自己是个顾问或服务型企业主，你就不会把一个企业主的抱怨看作是潜在的线索。</p><p>大多数人把那些老生常谈的建议看作是“令人尴尬（cringe）的”，因为大量的自嘲式梗图占据了他们的世界观，让他们把自己认同为平庸之辈。</p><p><a href="/letters/the-value-creator-a-new-internet-career-path-for-intelligent-people">社交媒体是实现你潜能的虚拟现实。</a></p><p>创业是长期主义者唯一合乎逻辑的选择。</p><p>个人品牌是你性格的延伸，是你持续发展的那个自我。</p><p>你的目标能吸引志同道合的玩家。</p><p>你的问题一旦被解决，就会成为你以产品或服务的形式帮助他人的方式。</p><p>你的想法就是那些占据追随者精神不动产并塑造他们自我认知的帖子。</p><p>通过社交媒体向大众写下和讲述你那美好的心智，就是你勾选出一个充实人生各项目标的方式。</p><h3 id="iii-ii-–-精神层面的繁衍" tabindex="-1">III.ii – 精神层面的繁衍 <a class="header-anchor" href="#iii-ii-–-精神层面的繁衍" aria-label="Permalink to &quot;III.ii – 精神层面的繁衍&quot;">​</a></h3><p>当你有了孩子，你就创造了一个“自我”。</p><p>是的，他们的肉体流着你的“血”，但<em>他们是谁</em>，却是你注入他们头脑中各种观念的结果。</p><p>明白了这一点，我们每天都在精神层面上进行繁衍。</p><p>你进行的每一次对话、传播的每一个观念、或捍卫的每一种信念，都是为了概念上的生存。</p><p>你的自我认知变得不朽，因为你的观念活在别人的头脑里。它们塑造着这个世界上的各种自我。</p><p>这就是为什么写作、演讲和创业如此回报丰厚。你会感受到那种因大规模影响他人生命而带来的连结感与充实感。</p><h3 id="iii-iii-–-我们正处于一场精神战争中" tabindex="-1">III.iii – 我们正处于一场精神战争中 <a class="header-anchor" href="#iii-iii-–-我们正处于一场精神战争中" aria-label="Permalink to &quot;III.iii – 我们正处于一场精神战争中&quot;">​</a></h3><p>在现代世界中，占据最多精神不动产的人，掌握着最大的权力。</p><p>想想詹姆斯·克莱尔 (James Clear)。</p><p>大多数人都知道他的《原子习惯》 (Atomic Habits) 这本书。</p><p>如果詹姆斯发布“习惯”这个词，他会获得成千上万的点赞和转发。</p><p>如果是其他任何人发布这个词，即使拥有相同数量的粉丝，他们获得的互动也会少得多。</p><p>这带出几个教益：</p><ul><li><strong>你留住注意力的时间越长，你的观念就越有力量。</strong> 书籍永远是至高无上的。播客和长视频紧随其后。短内容排在最后。但它们各有其用武之地。</li><li><strong>你的观念必须激发积极的行为改变。</strong> 如果你改变了某人的生活，他们会为你的成功一次又一次地归功于你。这意味着，即使人们没有消费你的作品，你的观念也在传播。</li><li><strong>当你的观念改变了人们的生活，你就能更长久地留住注意力。</strong> 如果一个人正在养成新习惯，詹姆斯·克莱尔的观念将一整天都占据着他们的头脑，从而塑造了他们的身份。他们变成了一半的克莱尔之子。</li></ul><p>短篇写作是为了最初吸引注意力和受众增长。长篇写作是为了滋养读者的心智与自我。</p><p>两者都是必要的，但只有短篇没有长篇，会让你陷入饱一顿饥一顿的死循环中。你的观念不会在人们脑海中长久留存。</p><p>人们试图在网上想说什么就说什么，结果失败了，正是因为他们没有领悟到这一点。</p><p>如果我写了一本书（这就是我这么做的原因），我就能在网上扩展我的语言，不再依赖那些“经过验证的”或“高表现的”话题来增长。</p><p>但新手不能跳过这一步。</p><p>除非你有一款极其畅销的 Offer（产品与服务方案），否则你的内容需要遵循注意力的渐进规律。你必须模仿经过验证的观念（比如病毒式推文或视频），同时通过长篇媒体慢慢建立权威。</p><p>无论是商业、你一生的事业，还是仅仅在网上写作，这都是一场观念的精神战争。</p><p>互动策略和增长黑客技术有助于传播你的观念，但那些观念会通过它们所创造的各个“自我”而在永恒中存活下去吗？</p><h3 id="iii-iv-–-创业的灵性" tabindex="-1">III.iv – 创业的灵性 <a class="header-anchor" href="#iii-iv-–-创业的灵性" aria-label="Permalink to &quot;III.iv – 创业的灵性&quot;">​</a></h3><p>自我发展是进入创业领域的“入门毒药”，因为你会意识到，提升他人就是提升自己的下一个层级。</p><p>注意力是你存在的根源。</p><p>它既是现实，也是你与现实的连结。</p><p>提升你自己，就是提升你集中注意力的地方。</p><p>大多数人都专注于下一次愉悦的体验。而智者则专注于那些寻欢作乐者试图逃避的问题。</p><p>发现一个问题。</p><p>学习如何解决它。</p><p>记录你是如何解决它的。</p><p>提炼成一个可复制的流程。</p><p>把它交给其他想获得帮助的人。</p><p>在线下做这件事，这叫成长。</p><p>在线上做这件事，这叫商业。</p><p>灵性，是感觉自己属于比自身更宏大事物的一部分。它是与那件一直存在的事物重聚：万物的统一与连结。</p><p>商业就是灵性，因为你正试图通过商品的交换来提升集体意识或发展。</p><h3 id="iii-v-–-行动步骤" tabindex="-1">III.v – 行动步骤 <a class="header-anchor" href="#iii-v-–-行动步骤" aria-label="Permalink to &quot;III.v – 行动步骤&quot;">​</a></h3><p>研究那些能产生注意力的东西。</p><p>心理学、媒体、设计、写作、营销、销售、说服、影响力，以及心智。</p><p>研究你自己。</p><p>研究你的思想、情绪、行动，并追溯它们的根源。别人投射到你身上的哪些目标、问题和信念，导致了你的这些思想、情绪和行动？</p><p>这听起来似乎很多，但你有一辈子的时间来搞定它，不是吗？</p><p>唯一其他的选项是什么？用麻痹神经的短暂快感来分散自己的注意力，让你在同样无聊的生活中越陷越深？</p><p><em>唯一比看到自己有多大潜能更令人痛苦的，是永远看不到自己有多大潜能。</em></p><p>你的教育应该，而且必须，反映出这一点。</p><h2 id="iv-–-精神变现" tabindex="-1">IV – 精神变现 <a class="header-anchor" href="#iv-–-精神变现" aria-label="Permalink to &quot;IV – 精神变现&quot;">​</a></h2><p>现在是2023年。</p><p>你拥有资源去重塑你的教育、增强你的技能组合，并在比拿个大学学位更短的时间内改变你的收入来源。</p><p>但这里有一个许多人都会掉进去的陷阱。</p><p>他们试图将虚荣、肤浅或快餐式的东西变现。</p><p>他们发布半裸的照片，结果只是在无法维持不健康饮食模式时失去了收入来源。</p><p>他们研究算法而不是人性，结果只是在技术变革时失去了收入。</p><p>他们研究“2023年最佳商业模式”，而不是营销、销售、说服和分发，结果只是在经济转向时失去了收入。</p><p>最好尽早意识到，智力是一个更可持续的变现杠杆（leverage）。</p><p>如果你保护好自己的心智，创造力、智慧、发展和品格都能成为你的收入来源。</p><h3 id="iv-i-–-学什么" tabindex="-1">IV.i – 学什么 <a class="header-anchor" href="#iv-i-–-学什么" aria-label="Permalink to &quot;IV.i – 学什么&quot;">​</a></h3><p>让我们从宏观的角度，来看看那些将在未来为你带来成功的技能。</p><p>我们想要精通的3大<em>应用</em>是：社交媒体、构建产品与服务（offer creation），以及引流。你的技能将通过这些途径得到引导，你的学习也将在此过滤。</p><p>你必须打造一个品牌、一个产品方案，并练习在这两者之间引流。这就是你赚钱的方式。</p><p>当你学习以下技能时，要从你正在构建的事物的视角去学。通过社交媒体品牌、引流和创造一个伟大产品的视角来过滤信息。</p><p><strong>IV.i.i – 常青技能</strong></p><p>写作、演讲、营销和销售，是你构建并向世界分发你所提供价值的方式。</p><p>社交媒体帖子、时事通讯、视频脚本以及所有其他媒体形式，都是写出来或说出来的。</p><p>然后，它们在营销和销售知识的加持下得到强化，因为这些知识是基于捕捉注意力和价值感知的心理学原理的。</p><p>这些不是可选项。</p><p>避免先去学任何其他技能。</p><p>真正的学习源于挣扎，而不是死记硬背。</p><p>你必须开始构建，而<strong>不是</strong>学习，当你遇到问题时，再去研究写作、演讲、营销和销售的课程和内容。</p><p><strong>IV.i.ii – 结果导向型技能</strong></p><p>当你牢牢掌握了这些常青技能后，你可以选择用其他结果导向型技能来强化它们。</p><p>这些技能包括但不限于任何能让你的社交媒体、引流或产品方案变得更好的其他技能：</p><ul><li>平面设计</li><li>网页设计与开发</li><li>搜索引擎优化</li><li>电子邮件营销</li><li>社交媒体营销代运营</li><li>别人叫你去学或去做的任何其他业务或技能。</li></ul><p>所有这些都将因常青技能而变得卓有成效。</p><p>仅仅孤立地学习它们，会让你极易被取代。</p><p>既然你正在新的虚拟现实中把个人品牌当成你的角色来构建，那你其实是在打造一套可以迁移到任何其他业务中的技能。</p><p>当你拥有100分的知识时，你才能创造出1分的产品或服务。</p><p>你在自己的品牌上积累的技能和经验越多，你获得的机会就越多。</p><p>人们会告诉你，在开始做社交媒体之前先建立一个业务。我认为那是一条通向充满不必要痛苦的人生的捷径，因为你根本不懂社交媒体。</p><h3 id="iv-ii-–-解剖你的头脑以寻找话题" tabindex="-1">IV.ii – 解剖你的头脑以寻找话题 <a class="header-anchor" href="#iv-ii-–-解剖你的头脑以寻找话题" aria-label="Permalink to &quot;IV.ii – 解剖你的头脑以寻找话题&quot;">​</a></h3><p>如果头脑是由形成思想、信念和行动的观念构成的，那么将它们分解成一个个单独的部分，对其进行研究、强化并重新对你的思维方式进行编程，就说得通了。</p><p><strong>你的目标是什么？</strong></p><p>写下实现这些目标的好处。</p><p><strong>挡在路上的问题是什么？</strong></p><p>写下克服这些问题时所涉及的情绪。</p><p><strong>为了达成目标，你必须</strong> <strong>获取</strong> <strong>哪些技能？</strong></p><p>写下你是如何应用这些技能的，以及你学到了什么。</p><p><strong>有哪10到20件事是你</strong> <strong>真心</strong> <strong>好奇想去学的？</strong></p><p>去研究它们，并用你自己的话，分享那些让你忍不住想告诉别人的大观点。</p><p><strong>你已经在消费哪些话题和兴趣内容？</strong></p><p>我喜欢看、读和听关于心理学、灵性、形而上学、商业、心智模式、心智模型等相关的内容。</p><p>建立一个包含3个广泛兴趣的话题树，把它拆解成一个个具体话题，然后再进一步拆解成写作想法。</p><p>然后，当你学习常青技能时，把这些作为提取经验教训的起点。</p><p><strong>你是新手、中阶还是高阶？</strong></p><p>市场上99%的人都是新手。</p><p>这往往是所有水平的人都会纠结的一点。</p><p>想想你消费了什么内容，以及你是如何消费它们的。</p><p>在社交媒体上，我喜欢阅读给新手的建议。它提醒了我需要专注的基础知识。</p><p>如果我想学点更高阶的东西，我不会试图在社交媒体上找。我有明确得多的搜索意图。我会直接去搜索，并且/或者买一本书或一门课程。</p><p>明白了这一点，即使你是高阶选手，也要为新手写作。</p><p>而如果你是个新手，放心吧，人们会从你的成长旅程中学习并获益的。</p><p><strong>社交媒体是一个集体大脑。</strong></p><p>你的工作是将你的角色作为品牌展示出来，并用写作记录下你的头脑所想。</p><p>观察你的思想，并试着把你的经历转化为经验教训。</p><p>我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>中会帮助你完成所有这些。</p><p>你的思维清晰度将会飙升。</p><h3 id="iv-iii-–-迭代你的大观点" tabindex="-1">IV.iii – 迭代你的大观点 <a class="header-anchor" href="#iv-iii-–-迭代你的大观点" aria-label="Permalink to &quot;IV.iii – 迭代你的大观点&quot;">​</a></h3><p>你每写100篇文章，只有少数几篇会是好文章。</p><p>这就是生活中一切事物的本质：不断试错。</p><p>你必须坦然接受失败，因为没有失败就不存在成功。</p><p>密切关注你最好的观点。</p><p>那些你最喜欢的，或者是数据表现最好的观点。</p><p>每个月，复盘你的写作，把最好的那些保存下来。</p><p>然后，站在更高经验水平的角度重新写它们。</p><p>你可以确信，当你这样做时，你的帖子数据表现会开始变得越来越好。</p><p>最终，你的头脑会按照你最好的观点来<em>思考</em>。这就是为什么作家、演讲者、播客主以及其他人听起来如此能言善道的原因。</p><p>他们已经训练了自己的大脑以大观点来运作。</p><h3 id="iv-iv-–-创造一个数据驱动的产品" tabindex="-1">IV.iv – 创造一个数据驱动的产品 <a class="header-anchor" href="#iv-iv-–-创造一个数据驱动的产品" aria-label="Permalink to &quot;IV.iv – 创造一个数据驱动的产品&quot;">​</a></h3><p>你的脑力变现之旅会为你提供大量反馈（如果你不开始，你就收不到这些反馈）。</p><p>注意：</p><ul><li><strong>你最佳观点的数据表现。</strong> 如果一个观点反响很好，这大概意味着基于这个观点的产品或服务也会卖得很好。</li><li><strong>其他人产品和观点的数据表现。</strong> 你必须成为一个观察者，而不是单纯的消费者。把社交媒体内容、落地页、漏斗、产品、服务和促销活动视为你自己灵感的弹药库。<em>卖那些已经在热卖的东西，但用你自己的名字和世界观来卖。</em></li><li><strong>人们告诉你他们想要什么。</strong> 随着你的成长，你的读者会开始直言不讳地表达他们想从你这里得到什么，以及什么对他们有帮助。在这上面加倍下注。</li><li><strong>人们问的问题。</strong> 你会注意到人们所遇问题的模式。你收到的问题越多，说明问题越大，人们付钱请你帮忙的可能性也就越高。</li></ul><p>如今你可以把你想要的任何东西变现。</p><p>我以前在<a href="https://youtube.com/playlist?list=PLB4ePXk6nBaeG3fD13NaRMsRsEc2iCsV4&amp;si=ClrQ044bDE6tR9rO" target="_blank" rel="noreferrer">YouTube的一人企业（one-person business）播放列表中</a>多次谈论过这个。</p><p>但你能走的最好的一条路是：<em>解决你自己的问题，并卖掉这个解决方案。</em></p><p>每个人都有同样的目标和问题。</p><p>他们只是通过不同的视角和世界观来看待它们。</p><p>你想要财务自由、健康、活力、爱情，以及改善健康、财富和人际关系所带来的一切好处。</p><p>有人会尝试做预算，而另一个人会开启一项副业。</p><p>你为了达成目标所做的事情，与别人要采取的方式截然不同。</p><p>你的工作就是通过谈论你的旅程，来吸引和你一样的人。</p><p>然后，把你实现目标的<em>路径</em>打包起来，把它卖出去。</p><p>这就是你塑造美丽心智的方式。</p><ul><li>理解你的心智躯体。</li><li>像在健身房里一样训练这具躯体。</li><li>要明白，现代的力量源于注意力或心智地盘。</li><li>将写作和商业作为自我认知和变现的载体。</li></ul><p>祝你周末余下时光愉快。</p><p>– 丹·柯伊 (Dan Koe)</p><hr><p><a href="/en/letters/mental-aesthetics-how-to-build-a-beautiful-mind">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',325))])}const q=a(h,[["render",d]]);export{g as __pageData,q as default};
